import{_ as a,o,c as i,a2 as s}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"发布流程","description":"","frontmatter":{},"headers":[],"relativePath":"zh/contribute/release.md","filePath":"zh/contribute/release.md","lastUpdated":1792766766000}'),t={name:"zh/contribute/release.md"};function c(l,e,d,r,n,h){return o(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="发布流程" tabindex="-1">发布流程 <a class="header-anchor" href="#发布流程" aria-label="Permalink to &quot;发布流程&quot;">​</a></h1><p>本页介绍 MeetCue 如何发布新版本：从修改版本号到 Scoop manifest 更新完成。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ol><li>确认默认分支上的 CI 全部通过。</li><li>对照各供应商的定价页面核对 <code>crates/core/data/pricing.json</code> 中的价格，并更新 <code>verified</code> 日期和 <code>updated</code>。</li><li>在 Windows 电脑上用默认分支的构建运行<a href="/meetcue/zh/test-checklist">实机测试清单</a>。</li><li>把两种语言<a href="/meetcue/zh/reference/changelog">更新日志</a>中 <strong>未发布</strong> 下的条目移到新版本标题下。</li></ol><h2 id="修改版本号" tabindex="-1">修改版本号 <a class="header-anchor" href="#修改版本号" aria-label="Permalink to &quot;修改版本号&quot;">​</a></h2><p>版本号只在根目录 <code>Cargo.toml</code> 的 <code>[workspace.package]</code> 中定义。同时把 <code>package.json</code>、<code>app/ui/package.json</code> 和 <code>docs/package.json</code> 改成相同的值；<code>npm run check:versions</code> 会检查它们是否一致。<code>tauri.conf.json</code> 从 Cargo 读取版本号。</p><h2 id="打标签" tabindex="-1">打标签 <a class="header-anchor" href="#打标签" aria-label="Permalink to &quot;打标签&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2.0</span></span></code></pre></div><h2 id="发布工作流做了什么" tabindex="-1">发布工作流做了什么 <a class="header-anchor" href="#发布工作流做了什么" aria-label="Permalink to &quot;发布工作流做了什么&quot;">​</a></h2><p>推送 <code>v*</code> 标签会在 Windows 上运行 <code>.github/workflows/release.yml</code>：</p><ol><li>用 Tauri CLI 构建 <code>MeetCue.exe</code>，不生成安装程序。</li><li>把 <code>MeetCue.exe</code>、<code>LICENSE</code> 和 README 文件打包为 <code>meetcue-win-x64.zip</code>，并计算 SHA-256 哈希。</li><li>创建 GitHub Release，上传 zip 并生成发布说明。</li><li>用新的版本号、下载地址和哈希更新 <code>bucket/meetcue.json</code>，并以仓库变量 <code>GIT_NAME</code> 和 <code>GIT_EMAIL</code> 的身份提交到默认分支。</li><li>在构建机上安装 Scoop，用更新后的 manifest 安装 MeetCue，确认 <code>MeetCue.exe --version</code> 输出新版本号。</li></ol><p>哈希只由工作流在上传 zip 的同一次运行中计算并提交。不要手动替换 Release 中的文件；需要修改时请发布新版本。</p><h2 id="发布之后" tabindex="-1">发布之后 <a class="header-anchor" href="#发布之后" aria-label="Permalink to &quot;发布之后&quot;">​</a></h2><ol><li>在 Windows 电脑上确认 <code>scoop update meetcue</code> 能升级到新版本。</li><li>确认文档站点显示了新的更新日志。</li></ol><h2 id="仓库设置" tabindex="-1">仓库设置 <a class="header-anchor" href="#仓库设置" aria-label="Permalink to &quot;仓库设置&quot;">​</a></h2><p>以下设置只需配置一次：</p><ul><li><strong>Settings › Pages</strong>：来源设为 <code>gh-pages</code> 分支。默认分支上 <code>docs/</code> 或 <code>errors.json</code> 有变化时，文档工作流会发布到这里。</li><li><strong>Settings › Secrets and variables › Actions › Variables</strong>：设置 <code>GIT_NAME</code> 和 <code>GIT_EMAIL</code>，供工作流提交时使用。</li><li>仓库必须是公开的，否则 Scoop 无法下载 Release 中的文件。</li></ul>`,17)])])}const k=a(t,[["render",c]]);export{u as __pageData,k as default};
